#include <iostream>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int ia, ib, fa, fb;
    cin >> ia >> ib >> fa >> fb;

    int da = ia ^ fa; // A precisa mudar de estado?
    int db = ib ^ fb; // B precisa mudar de estado?

    int ans;
    if (da == 0 && db == 0) {
        // Nada precisa mudar: 0 apertos
        ans = 0;
    } else if (da == 0 && db == 1) {
        // Só B muda: C2 (1 aperto) deixa B certa, mas também muda A.
        // Precisamos de outro C2 ou combinar C1+C2 -> mínimo 2 apertos.
        ans = 2;
    } else if (da == 1 && db == 0) {
        // Só A muda: basta apertar C1 uma vez.
        ans = 1;
    } else {
        // Ambas mudam: basta apertar C2 uma vez.
        ans = 1;
    }

    cout << ans << "\n";
    return 0;
}
